\section{All-genus local/relative correspondence}\label{Section:loc/rel}
In this section, we
give a new way to package the all-genus local/relative correspondence established in \cite{BFGW}.

Let $E$ be a smooth effective anticanonical divisor on a del Pezzo surface $S$. Let $\bM_{g}(K_S,\beta)$ be the moduli space of stable maps to the total space of $K_S$ with genus $g$, curve class $\beta$. We define the local Gromov-Witten invariants
\[ N_{g,\beta}^{K_S} \coloneqq \int_{[\bM_g(K_S,\beta)]^\vir} 1 \,.\]
Let $\bM_{g}(S/E,\beta)$ be the moduli space of genus $g$ relative stable maps of class $\beta$ to $(S,E)$ with only one contact condition of maximal tangency along $E$. It has virtual dimension $g$ and we define the maximal contact Gromov-Witten invariants of the pair $(S,E)$
\[ N_{g,\beta}^{S/E}\coloneqq \int_{[\bM_g(S/E,\beta)]^\vir}
(-1)^g \lambda_g \,.\]
Let $N_{E/S}$ be the normal bundle to $E$ in $S$. We consider the rank $2$ vector bundle
$N \coloneqq N_{E/S}\oplus N_{E/S}^{\vee}$ over $E$
and the anti-diagonal scaling action of $\GM$ on $N$ with weight $1$ on $N_{E/S}$ and weight $-1$ on $N_{E/S}^{\vee}$.
We denote by $t$ the corresponding equivariant parameter. Let
$\bM_{g,n}(E,d_E)$ be the moduli space of $n$-pointed, genus $g$ stable maps of degree $d_E$ to the elliptic curve $E$. We define the local invariants of $E$ to be
\begin{equation*}
N_{g,d_E}^{\Etw}(\bd)
\coloneqq \int_{[\bM_{g,n}(E,d_E)]^{\vir}} \left( \prod_{j=1}^n \frac{t \ev_j^*\omega}{t-d_j \psi_j} \right) e_{\GM}(-R^{\bullet}\pi_*f^{*}N)
\end{equation*}
where $\bd=(d_1,d_2,\cdots,d_n)$ is a tuple of positive integers, $\psi_j$ are cotangent line classes, $\omega$ is the point class of $E$, $\pi$ is the universal domain curve and $f$ is the universal stable map.

The local invariants
$N_{g,\beta}^{K_S}$ and relative invariants $N_{g,\beta}^{S/E}$ can be related via the following all-genus local/relative correspondence \cite{BFGW}:
\begin{equation}\label{eqn:loc/rel_origin}
\begin{split}
N_{g,\beta}^{K_{S}}
=& \frac{(-1)^{\beta \cdot E-1}}{\beta
\cdot E} N_{g,\beta}^{S/E}+ \\
&\sum_{n\geq 0}\sum_{\substack{g=g_0+g_1+\dots+g_n\\
\beta=d_E[E]+\beta_1+\dots +\beta_n \\
d_E\geq 0,\,\beta_j\cdot E>0}}
\frac{N_{g_0,d_E}^{\Etw}(\boldsymbol{\beta} \cdot E)}{|\Aut (\boldsymbol{\beta},\bg)|}
\prod_{j=1}^n \left((-1)^{\beta_j \cdot E}
(\beta_j \cdot E)
N_{g_j,\beta_j}^{S/E}\right).
\end{split}
\end{equation}
Here
\[\boldsymbol{\beta}\coloneqq(\beta_1,\dots,\beta_n )\,, \qquad \boldsymbol{\beta} \cdot E \coloneqq(\beta_1\cdot E,\dots,\beta_n \cdot E) \,,\]
\[\bg\coloneqq (g_1,\cdots,g_n)\,,\quad  \frac{1}{|\Aut (\boldsymbol{\beta},\bg)|}\coloneqq \frac{1}{|\Aut ((\beta_1,g_1),\cdots,(\beta_n,g_n))|},\]
and we simply set $N_{g_0,d_E}^{\Etw}(\boldsymbol{\beta} \cdot E)$ to be zero if the corresponding moduli is unstable.

\subsection{A new way to package the all-genus local/relative correspondence}
We introduce the following generating series by summing over genera:
$$
\W_{\beta}^{K_S}(\hbar)\coloneqq \sum_{g \geq 0} N_{g,\beta}^{K_{S}} \hbar^{2g-2}, \qquad
 \V_{\beta}^{S/E}(\hbar)\coloneqq {(-1)^{\beta\cdot E-1}}  \sum_{g \geq 0}  \frac{N_{g,\beta}^{S/E}}{\beta\cdot E} \hbar^{2g-1},
$$
$$
F^{E,\tw}_{d_E,\boldsymbol{\beta}}(\hbar)\coloneqq \sum_{g \geq 0}\left( \prod_{i=1}^n(-(\beta_i\cdot E)^2)\right)\cdot N_{g,d_E}^{\Etw}(\boldsymbol{\beta} \cdot E) \hbar^{2g-2+n}.
$$
Then we can package the all-genus local/relative correspondence \eqref{eqn:loc/rel_origin} as
\begin{prop}\label{prop:local/rel}
For a fixed curve class $\beta>0$, we have
\begin{align*}
\W^{K_S}_\beta(\hbar)   =  \ & \sum_{0\leq d_E[E]\leq \beta}  \sum_{\boldsymbol{\beta}=(\beta_1,\cdots,\beta_n)\atop |\boldsymbol{\beta}|+d_E[E] =\beta}  \frac{1}{|\Aut(\boldsymbol{\beta})|}  F^{E,\tw}_{d_E,\boldsymbol{\beta}}(\hbar) \prod_{i}  \V^{S/E}_{\beta_i}(\hbar)
\\  =  \ &    \    \frac{(\beta\cdot E) \V^{S/E}_{\beta}(\hbar)}{ 2 \sin \frac{(\beta\cdot E) \hbar}{2} }
    + \sum_{0< d_E[E]\leq \beta}  \sum_{\boldsymbol{\beta}=(\beta_1,\cdots,\beta_n)\atop |\boldsymbol{\beta}|+d_E[E] =\beta} \frac{1}{|\Aut(\boldsymbol{\beta})|}  F^{E,\tw}_{d_E,\boldsymbol{\beta}}(\hbar) \prod_{i}  \V^{S/E}_{\beta_i}(\hbar).
\end{align*}
\end{prop}
Here $[E]$ is the curve class associated to $E$,
\[ |\boldsymbol{\beta}|\coloneqq \sum_{i=1}^n \beta_i,\qquad \frac{1}{|\Aut (\boldsymbol{\beta})|}\coloneqq \frac{1}{|\Aut (\beta_1,\cdots,\beta_n)|},\]
and the second equality follows from the fact that $$F^{E,\tw}_{d_E=0,\boldsymbol{\beta}=(\beta_1,\dots,\beta_n)}(\hbar)=
\begin{cases}
\frac{\beta_1\cdot E}{2 \sin \frac{(\beta_1\cdot E) \hbar}{2} }, & \text{ if } n=1,\\
0, & \text{ if } n>1.
\end{cases}
$$


\subsection{A graph sum formula}  \label{sec:graphsum}
Using the equation in Proposition \ref{prop:local/rel},
one can iteratively
solve for $\V^{S/E}$ in terms of $\W^{K_S}$ and $F^{E,\tw}$ as follows.

Let $T$ be a rooted tree\footnote{A rooted tree is a tree with a special vertex labeled as the "root" the of tree. It  serves as a point of reference for other vertices in the tree.}  together with the following assignments:

\begin{enumerate}
\item[(i)] $t:V_T\longrightarrow \{0,1\}$, where we use $V_T$ to denote the set of vertices.
\item[(ii)] $d^0:t^{-1}(0)\longrightarrow \Z_{>0}$, $d^1:t^{-1}(1)\longrightarrow H_2(S,\Z)$.
\item[(iii)] $d_2:E_T\longrightarrow H_2(S,\Z)$, where we use $E_T$ to denote the set of edges.
\end{enumerate}
The first assignment $t$ gives a labeling of vertices. A vertex labeled by $0$ will be represented by a circle and a vertex labeled by $1$ will be represented by a square. The rest assignments give another labeling of vertices and edges by curve classes of $S$. We require these labelings to satisfy:
\begin{enumerate}
\item[(1)] If the number of vertices $|V_T|>1$, then vertices labeled by $1$ are always leaves\footnote{A leaf in a rooted tree is any vertex having no children. So the rooted vertex is always not a leaf if the number of vertices is greater than $1$.} of the rooted tree $T$.
\item[(2)] The images of $d^1$ and $d_2$ are nonzero effective curve classes.
\item[(3)] For any vertex $v_i$ labeled by $0$ which is not the rooted vertex, we use $e^i_0,e^i_1,\cdots,e^i_{n_i}$ to denote the edges incident to $v_i$ where $e_0^i$ is the unique edge belongs to the path connecting $v_i$ to the rooted vertex. We require
\[d_2(e_0^i)=d^0(v_i)[E]+\sum_{k=1}^{n_i}d_2(e_k^i).\]
If $|V_T|>1$, then for each vertex $v_i$ labeled by $1$, there is a unique edge $e_0^i$ incident to $v_i$. We further require
$$
d_2(e_0^i)=d^1(v_i).
$$
\end{enumerate}
Given such a $T\in \RT$, we define the degree of $T$ to be
\[\sum_{v\in t^{-1}(1)}d^1(v)+\sum_{v\in t^{-1}(0)} d^0(v)[E].\]
Two labeled rooted trees are called isomorphic if there exists an isomorphism\footnote{An isomorphism between rooted trees always maps rooted vertex to rooted vertex.} between the underlying rooted trees which commutes with all the labelings. We use $\RT$ to denote the isomorphism classes of all such labeled rooted trees. We further use $\RT_\beta$ to denote the labeled rooted trees in $\RT$ with fixed curve class $\beta$.

