\end{split}
\end{equation}
where $|\Aut(
T)|$ stands for the number of automorphism of $T$ as a labeled rooted tree, $e^i_1,\cdots,e^i_{n_i}$ are the edges incident to $v_i$
which do not belong to the path connecting $v_i$ and the rooted vertex.
\end{cor}
The second equality in Corollary \ref{cor:rel/local} follows from the fact that there is only one rooted tree $T\in\RT_\beta$ such that $t^{-1}(0)=\emptyset$ and the corresponding contribution is
\[\frac{2\sin{\frac{(\beta\cdot E)\hbar}{2}}}{\beta\cdot E}\W^{K_S}_\beta.\]
For the labeled rooted tree $T$ given above, the contribution $\Cont_{T}$ is
\[-\frac{1}{2}\frac{2\sin{\frac{21\hbar}{2}}}{21}\frac{2\sin{\frac{18\hbar}{2}}}{18}\frac{2\sin{\frac{18\hbar}{2}}}{18}\frac{2\sin{\frac{6\hbar}{2}}}{6}\frac{2\sin{\frac{6\hbar}{2}}}{6}F^{E,\tw}_{2,\{7,6,6\}}
F^{E,\tw}_{2,\emptyset}F^{E,\tw}_{1,\{2,2\}}\W^{K_{\PP^2}}_2\W^{K_{\PP^2}}_2\W^{K_{\PP^2}}_6.\]


\section{Gromov-Witten invariants of local elliptic curves}\label{sec:localcurvesfm}
In this section, we give an explicit formula for $F^{E,\tw,\bullet}_{d_E,\boldsymbol{\beta}}$ by extending the topological quantum field theory (TQFT) formalism of Bryan and Pandharipande \cite{BP08} to include stationary insertions. The superscript
$\bullet$ in $F^{E,\tw,\bullet}_{d_E,\boldsymbol{\beta}}$ indicates that we consider possibly disconnected invariants\footnote{Following \cite{BP08}, we require the degree of each connected domain curve to be nonzero.}.

Let $\rho=(\rho_1\geq \rho_2\geq \cdots)$ be a partition of $d_E$. It corresponds to a Young diagram. We use $c_{\rho}$ to denote the total sum of the contents of all its boxes where the content of a box at the $(i,j)$-position is $j-i$. We further set $k$ to be the degree of the normal bundle $N_{E/S}$ or equivalently $k=K_S^2$, and set
\begin{equation}\label{eqn:tildeE}
\tilde{e}(\rho,z) \coloneqq \sum_{i=1}^{\infty}(e^{z (\rho_i-i+\frac{1}{2})}-e^{z(-i+\frac{1}{2})}),
\end{equation}
where we extend $\rho$ to an infinite sequence by appending zeros.

\begin{thm}\label{thm:keythm}
\[F^{E,\tw,\bullet}_{d_E,\boldsymbol{\beta}}(\hbar)=\sum_{|\rho|=d_E}  (-1)^{kd_E }e^{k c_\rho \sqrt{-1}   \hbar} \prod_{i=1}^n (-\beta_i\cdot E)\frac{\tilde{e}(\rho,(\beta_i\cdot E)\sqrt{-1}\hbar)}{\sqrt{-1}}\]
where $|\rho|=\sum_i\rho_i$.
\end{thm}
\begin{proof}
When there are no interior markings, i.e., $\beta=\emptyset$, Theorem \ref{thm:keythm} specializes to
\begin{equation}\label{eqn:empty}
F^{E,\tw,\bullet}_{d_E,\emptyset}(\hbar)=\sum_{|\rho|=d_E}  (-1)^{kd_E }e^{ k  c_\rho\sqrt{-1}  \hbar}
\end{equation}
which is simply Corollary 7.4 of \cite{BP08}. It was proven by the
TQFT formalism of \cite{BP08}. When there are interior markings, we need to extend the TQFT formalism to include stationary insertions. The key
is to compute the following level $(0,0)$ series with one interior marking\footnote{The level series were introduced in \cite{BP08} when there are no interior markings. We borrow the notation from \cite{BP08} for level series. But our level series contain stationary insertions. So we add a tilde to indicate the difference.}:
\[\widetilde{\GW}(0|0,0)^{\alpha}(\beta_i)\coloneqq \hbar^{d_E+l(\alpha)}(-t^2)^{l(\alpha)}\mathfrak{z}(\alpha)\tilde{Z}(N)_{\alpha}(\beta_i)\]
where $\alpha$ is a partition of $d_E$, $l(\alpha)$ denotes its length, and
\[\mathfrak{z}(\alpha)=\prod_i m_i(\alpha)!i^{m_i(\alpha)}\]
with $m_i(\alpha)$ being the multiplicity of $i$ in $\alpha$. The term $\tilde{Z}(N)_{\alpha}(\beta_i)$ is defined as
\[\tilde{Z}(N)_{\alpha}(\beta_i)\coloneqq \sum_{g\in \Z}\hbar^{2g-1}(-(\beta_i\cdot E)^2)\int_{[\bM^{\bullet}_{g,1}(\PP^1/0,\alpha)]^{\vir}}\frac{t \ev_1^*(\omega)}{t-(\beta_i\cdot E) \psi_1}e_{\GM}(-R^{\bullet}\pi_* f^*(\mathcal{O}\oplus \mathcal{O}))\]
where $\bM^{\bullet}_{g,1}(\PP^1/0,\alpha)$ is the possibly disconnected moduli space of genus $g$ relative stable maps to $(\PP^1,0)$ with one interior marking and tangency condition $\alpha$,
$\GM$ acts anti-diagonal on the direct sum of two trivial line bundles, and $t$ is the equivariant parameter. By Mumford's relation and dimension constraint, we have
\[\widetilde{\GW}(0|0,0)^{\alpha}(\beta_i)=\sum_{g\in \Z}\hbar^{k+1}(-1)^{l(\alpha)+g}t^{l(\alpha)-d_E}\mathfrak{z}(\alpha)\int_{[\bM^{\bullet}_{g,1}(\PP^1/0,\alpha)]^{\vir}}(\beta_i\cdot E)^{k+2}\psi_1^k \ev_1^*(\omega).\]
with
\begin{equation}\label{eqn:g2k}
k=d_E+2g-2+l(\alpha).
\end{equation}
According to \cite[Lemma 7.5]{BP08}, up to some factors of $t$, the Frobenius algebra associated to the TQFT in the anti-diagonal case is isomorphic to the center of the group algebra of the symmetric group. The idempotent basis are indexed by partitions of $d_E$ (equation (20) and (21) of \cite{BP08}):
\[v_{\rho}=\frac{\dim \rho}{(d_E)!}\sum_{\alpha}(\sqrt{-1}t)^{l(\alpha)-d_E}\chi^{\rho}_{\alpha}e_{\alpha}\]
or equivalently, we have
\[e_{\alpha}=(\sqrt{-1}t)^{d_E-l(\alpha)}\sum_{\rho}\frac{(d_E)!}{\dim \rho}\frac{\chi^{\rho}_{\alpha}}{\mathfrak{z}(\alpha)}v_{\rho}.\]
So if we write $\sum_{\alpha}\widetilde{\GW}(0|0,0)^{\alpha}(\beta_i)e_{\alpha}$ in terms of the idempotent basis $v_{\rho}$, the coefficient before $v_{\rho}$ is simply
\begin{equation}\label{eqn:bigsum}
\gamma_{\rho}(\beta_i)=\sum_{k\geq 0} (\sqrt{-1})^{k+2}\hbar^{k+1}(\beta_i\cdot E)^{k+2}\sum_{|\alpha|=d_E}\frac{(d_E)!}{\dim \rho}\chi^{\rho}_{\alpha}\int_{[\bM^{\bullet}_{g,1}(\PP^1/0,\alpha)]^{\vir}}\psi_1^k \ev_1^*(\omega).
\end{equation}
We are ready to extend the TQFT formalism of \cite{BP08} to include stationary insertions:
\[F^{E,\tw,\bullet}_{d_E,\boldsymbol{\beta}}=\sum_{|\rho|=d_E}  (-1)^{kd_E }e^{kc_\rho \sqrt{-1}    \hbar} \prod_{i=1}^n \gamma_{\rho}(\beta_i)\]
which can be proved using the degenerating formula as in \cite{BP08}.

We are left to determine $\gamma_{\rho}(\beta_i)$. By the Gromov-Witten/Hurwitz correspondence \cite{OP1}, we know that
\[\sum_{|\alpha|=d_E}\frac{(d_E)!}{\dim \rho}\chi^{\rho}_{\alpha}\int_{[\bM^{\bullet}_{g,1}(\PP^1/0,\alpha)]^{\vir}}\tau_k(\omega)=[z^{k+1}]\tilde{e}(\rho,z)\]
where $[z^{k+1}]$ means we take the $z^{k+1}$-coefficient of $\tilde{e}(\rho,z)$. Note that we require the degree of each connected domain curve to be nonzero, so we need to remove the degree zero contributions from the Gromov-Witten/Hurwitz correspondence. After plugging into the \eqref{eqn:bigsum}, it becomes
\[\sum_{k\geq 0} (\sqrt{-1})^{k+2}\hbar^{k+1}(\beta_i\cdot E)^{k+2}[z^{k+1}]\tilde{e}(\rho,z)=(-\beta_i\cdot E)\frac{\tilde{e}(\rho,(\beta_i\cdot E)\sqrt{-1}\hbar)}{\sqrt{-1}}.\]
From the above discussion, we may conclude that
\[F^{E,\tw,\bullet}_{d_E,\boldsymbol{\beta}}(\hbar)=\sum_{|\rho|=d_E}  (-1)^{kd_E }e^{kc_\rho \sqrt{-1}\hbar} \prod_{i=1}^n (-\beta_i\cdot E)\frac{\tilde{e}(\rho,(\beta_i\cdot E)\sqrt{-1}\hbar)}{\sqrt{-1}}.\]
\end{proof}


\begin{cor}\label{cor:rat}
Under the change of variables $y=e^{i\hbar}$, we have
\[F^{E,\tw,\bullet}_{d_E,\boldsymbol{\beta}}(\hbar)\in \left(\prod_{i=1}^n\frac{y^{\frac{\beta_i\cdot E}{2}}-y^{-\frac{\beta_i\cdot E}{2}}}{\sqrt{-1}}\right)\mathbb{Q}[y,y^{-1}]\]
where $\boldsymbol{\beta}=(\beta_1,\beta_2,\cdots,\beta_n)$.
\end{cor}

\begin{proof}
By Theorem \ref{thm:keythm}, we know that
\[F^{E,\tw,\bullet}_{d_E,\boldsymbol{\beta}}(\hbar)=\sum_{|\rho|=d_E}  (-1)^{kd_E }e^{kc_\rho \sqrt{-1}\hbar} \prod_{i=1}^n (-\beta_i\cdot E)\frac{\tilde{e}(\rho,(\beta_i\cdot E)\sqrt{-1}\hbar)}{\sqrt{-1}}.\]
For each partition $\rho$, we know that
\[ (-1)^{kd_E }e^{ k c_\rho \sqrt{-1}  \hbar}\in \Q[y,y^{-1}]\]
after the change of variables $y=e^{i\hbar}$. We only need to show each
\[(-\beta_i\cdot E)\frac{\tilde{e}(\rho,(\beta_i\cdot E)\sqrt{-1}\hbar)}{\sqrt{-1}}\in \left(\frac{y^{\frac{\beta_i\cdot E}{2}}-y^{-\frac{\beta_i\cdot E}{2}}}{\sqrt{-1}}\right)\mathbb{Q}[y,y^{-1}]. \]
Let
\[S(\rho)=\{\rho_1-\frac{1}{2}>\rho_2-\frac{3}{2}>\cdots>\rho_k-k+\frac{1}{2}>\cdots\}\in \Z+\frac{1}{2}\]
and set $S_{+}(\rho)=S(\rho)\backslash \left(\Z_{\leq 0}-\frac{1}{2}\right)$, $S_{-}(\rho)= \left(\Z_{\leq 0}-\frac{1}{2}\right)\backslash S(\rho)$. We have $|S_{+}(\rho)|=|S_{-}(\rho)|$. So we may assume that
\[S_{+}(\rho)=\{m_1,m_2,\cdots,m_s\},\quad S_{-}(\rho)=\{n_1,n_2,\cdots,n_s\} \]
where $m_i,n_i$ are half-integers. Then we may express $\tilde{e}(\rho,(\beta_i\cdot E)\sqrt{-1} \hbar)$ as
\[\tilde{e}(\rho,(\beta_i\cdot E)\sqrt{-1}\hbar)=\sum_{k=1}^s(e^{(\beta_i\cdot E)m_k\sqrt{-1}\hbar}-e^{(\beta_i\cdot E)n_k\sqrt{-1}\hbar }).\]
Each summand
\begin{align*}
&e^{(\beta_i\cdot E)m_k\sqrt{-1}\hbar}-e^{(\beta_i\cdot E)n_k\sqrt{-1}\hbar }\\
=&(e^{\frac{\beta_i\cdot E}{2}\sqrt{-1}\hbar }-e^{-\frac{\beta_i\cdot E}{2}\sqrt{-1}\hbar})\left(\sum_{l=n_k+1/2}^{m_k-1/2}e^{(\beta_i\cdot E)l\sqrt{-1}\hbar }\right)\in \left(\frac{y^{\frac{\beta_i\cdot E}{2}}-y^{-\frac{\beta_i\cdot E}{2}}}{\sqrt{-1}}\right)\mathbb{Q}[y,y^{-1}]
\end{align*}
after the change of variables $y=e^{i\hbar}$. It follows that
\[(-\beta_i\cdot E)\frac{\tilde{e}(\rho,(\beta_i\cdot E)\sqrt{-1}\hbar)}{\sqrt{-1}}\in \left(\frac{y^{\frac{\beta_i\cdot E}{2}}-y^{-\frac{\beta_i\cdot E}{2}}}{\sqrt{-1}}\right)\mathbb{Q}[y,y^{-1}]. \]
\end{proof}

Using Corollary \ref{cor:rat}, we can deduce the following lemma which will play an important role in the proof of Theorem \ref{thm:main0}.
\begin{lem}\label{lem:key}
For each rooted tree $T\in\RT_\beta$ such that $t^{-1}(0)\neq \emptyset$, we have
\[\Cont_T\in \Q[y,y^{-1}]\]
after the change of variables $y=e^{i\hbar}$.
\end{lem}
\begin{proof}
Recall that
\[
\Cont_{T}=\frac{1}{|\Aut(T)|}
\prod_{e\in E_T}\frac{2\sin\frac{(d_2(e)\cdot E)\hbar}{2}}{d_2(e)\cdot E}\prod_{v_i\in t^{-1}(0)}\left(-F^{E,\tw}_{d^0(v_i),\{d_2(e_1^i),d_2(e_2^i),\cdots,d_2(e_{n_i}^i)\}}\right)\prod_{v_i\in t^{-1}(1)}\W^{K_S}_{d^1(v_i)}.
\]
By Corollary \ref{cor:rat}, we know that
\[F^{E,\tw,\bullet}_{d^0(v_i),\{d_2(e_1^i),d_2(e_2^i),\cdots,d_2(e_{n_i}^i)\}} \in \left(\prod_{k=1}^{n_i}\frac{y^{\frac{d_2(e_{k}^i)\cdot E}{2}}-y^{-\frac{d_2(e_{k}^i)\cdot E}{2}}}{\sqrt{-1}}\right)\mathbb{Q}[y,y^{-1}].\]
Since connected invariants can be determined from the disconnected invariants by inclusion and exclusion, we still have
\[F^{E,\tw}_{d^0(v_i),\{d_2(e_1^i),d_2(e_2^i),\cdots,d_2(e_{n_i}^i)\}} \in \left(\prod_{k=1}^{n_i}\frac{y^{\frac{d_2(e_{k}^i)\cdot E}{2}}-y^{-\frac{d_2(e_{k}^i)\cdot E}{2}}}{\sqrt{-1}}\right)\mathbb{Q}[y,y^{-1}]\]
for connected invariants. Combining with the fact that
\[2\sin\frac{(d_2(e)\cdot E)\hbar}{2}=\frac{y^{\frac{d_2(e)\cdot E}{2}}-y^{
\frac{-d_2(e)\cdot E}{2}}}{\sqrt{-1}},\quad y=e^{i\hbar}.\]
We may deduce that
\begin{equation}\label{eqn:midcont}
\Cont_{T}\in\left(\prod_{e\in E}(y^{\frac{d_2(e)\cdot E}{2}}-y^{
\frac{-d_2(e)\cdot E}{2}})^2\prod_{v_i\in t^{-1}(1)}\W_{d^1(v_i)}^{K_S}\right)\Q[y,y^{-1}].
\end{equation}
If $t^{-1}(1)$ is empty, then we already see that
\begin{equation*}
\Cont_{T}\in\Q[y,y^{-1}].
\end{equation*}
If $t^{-1}(1)$ is not empty, then by definition for each $v_i\in t^{-1}(1)$, there is a unique edge $e_0^i\in E$ incident to $v_i$. Then considering the factor
\[(y^{\frac{d_2(e_0^i)\cdot E}{2}}-y^{
\frac{-d_2(e_0^i)\cdot E}{2}})^2\W_{d^1(v_i)}^{K_S}\]
in \eqref{eqn:midcont}.
We can write $\W_{d^1(v_i)}^{K_S}$ in terms of  Gopakumar-Vafa invariants $n_{g,\beta}$ of $K_S$:
\begin{align*}
\W_{d^1(v_i)}^{K_S} &=\sum_{k|d^1(v_i)} \frac{1}{k(2\sin(k\hbar/2))^2}\sum_{g\geq 0}n_{g,d^1(v_i)/k}\left(2\sin(\frac{k\hbar}{2})\right)^{2g}\\
&=\sum_{k|d^1(v_i)} \frac{-1}{k(y^{\frac{k}{2}}-y^{-\frac{k}{2}})^2}\sum_{g\geq 0}n_{g,d^1(v_i)/k}(-1)^g(y^{\frac{k}{2}}-y^{-\frac{k}{2}})^{2g},\quad y=e^{i\hbar}.
\end{align*}
By requirement (3) in the definition of a labeled rooted tree, $d^1(v_i)=d_2(e_0^i)$, so:
\[(y^{\frac{d_2(e_0^i)\cdot E}{2}}-y^{
\frac{-d_2(e_0^i)\cdot E}{2}})^2\W_{d^1(v_i)}^{K_S}\in \Q[y,y^{-1}].\]
Hence,
\begin{equation*}
\Cont_{T}\in\Q[y,y^{-1}].
\end{equation*}
\end{proof}


\section{Applications of the all-genus local/relative correspondence} \label{sec:pfCGKT}
Recall that in Section \ref{Section:loc/rel}, we give a new way to package the all-genus local/relative correspondence. Here and in the next section, we present two applications of this correspondence.

\subsection{Proof of Theorem \ref{thm:main0}}
The first application establishes that Choi-van Garrel-Katz-Takahashi's conjecture follows from Bousseau's conjectural refined sheaves/Gromov-Witten correspondence. Since the refined sheaves/Gromov-Witten correspondence is known for $S=\mathbb{P}^2$, our result proves Choi-van Garrel-Katz-Takahashi's conjecture in this case.

To begin, we reformulate Choi-van Garrel-Katz-Takahashi's conjecture as follows:

\begin{conj}[=Conjecture \ref{conj:main0}]\label{conj:main}
$\Omega_{\beta}\left(y^{\frac{1}{2}}\right)$ can be divided by the shifted Poincar\'e polynomial of $\PP^{\beta\cdot E-1}$, i.e.,
\[\frac{\Omega_{\beta}\left(y^{\frac{1}{2}}\right)}{{\frac{\left(y^{\frac{1}{2}}\right)^{\beta\cdot E}-\left(y^{\frac{1}{2}}\right)^{-\beta\cdot E}}{y^{\frac{1}{2}}-y^{-\frac{1}{2}}}}}\]
is a palindromic Laurent polynomial of $y$.
\end{conj}

\begin{thm}[=Theorem \ref{thm:main0}]\label{thm:main}
Assuming Conjecture \ref{conj:rsh/GW} holds, then Conjecture \ref{conj:main} holds. In particular, Conjectures  \ref{conj:main} holds when $S=\PP^2$.
\end{thm}
\begin{proof}[Proof of Theorem \ref{thm:main}]


Recall by Corollary \ref{cor:rel/local} of the local/relative correspondence,
\[\V^{S/E}_\beta=\frac{2\sin{\frac{(\beta\cdot E)\hbar}{2}}}{\beta\cdot E}\left(\W^{K_S}_\beta+\sum_{T\in \RT_\beta,\atop t^{-1}(0)\neq \emptyset} \Cont_{T}\right).\]
Assuming Conjecture \ref{conj:rsh/GW} holds, we have
\[\V^{S/E}_\beta=\sqrt{-1} \sum_{k|\beta} \frac{1}{k^2} \frac{(-1)^{\frac{\beta^2}{k^2}+1}\Omega_{\frac{\beta}{k}}\left(y^{\frac{k}{2}}\right)}{y^{\frac{k}{2}}-y^{-\frac{k}{2}}}. \]
Combining them, we get
\[\sum_{k|\beta} \frac{-1}{k(y^{\frac{k}{2}}-y^{-\frac{k}{2}})^2} \frac{\frac{\beta\cdot E}{k}(-1)^{\frac{\beta^2}{k^2}+1}\Omega_{\frac{\beta}{k}}\left(y^{\frac{k}{2}}\right)}{\frac{\left(y^{\frac{k}{2}}\right)^{\frac{\beta\cdot E}{k}}-\left(y^{\frac{k}{2}}\right)^{-\frac{\beta\cdot E}{k}}}{y^{\frac{k}{2}}-y^{-\frac{k}{2}}}}=\W_\beta^{K_S}+\sum_{T\in \RT_\beta,\atop t^{-1}(0)\neq \emptyset} \Cont_{T}.\]
We can write $\W_\beta^{K_S}$ in terms of Gopakumar-Vafa invariants $n_{g,\beta}$ of $K_S$:
\begin{align*}
\W_\beta^{K_S} &=\sum_{k|\beta} \frac{1}{k(2\sin(k\hbar/2))^2}\sum_{g\geq 0}n_{g,\frac{\beta}{k}}\left(2\sin(\frac{k\hbar}{2})\right)^{2g}\\
&=\sum_{k|\beta} \frac{-1}{k(y^{\frac{k}{2}}-y^{-\frac{k}{2}})^2}\sum_{g\geq 0}n_{g,\frac{\beta}{k}}(-1)^g(y^{\frac{k}{2}}-y^{-\frac{k}{2}})^{2g}.
\end{align*}
So after plugging into the previous equality, we get
\begin{equation}\label{eqn:sheaf/GW}
\begin{split}
\sum_{k|\beta} \frac{-1}{k(y^{\frac{k}{2}}-y^{-\frac{k}{2}})^2} \left(\frac{\frac{\beta\cdot E}{k}(-1)^{\frac{\beta^2}{k^2}+1}\Omega_{\frac{\beta}{k}}\left(y^{\frac{k}{2}}\right)}{\frac{\left(y^{\frac{k}{2}}\right)^{\frac{\beta\cdot E}{k}}-\left(y^{\frac{k}{2}}\right)^{-\frac{\beta\cdot E}{k}}}{y^{\frac{k}{2}}-y^{-\frac{k}{2}}}}-\sum_{g\geq 0}n_{g,\frac{\beta}{k}}(-1)^g(y^{\frac{k}{2}}-y^{-\frac{k}{2}})^{2g}\right)&\\
=\sum_{T\in \RT_\beta,\atop t^{-1}(0)\neq \emptyset} \Cont_{T}.
\end{split}
\end{equation}
Note that each
\[ \frac{-1}{(y^{\frac{k}{2}}-y^{-\frac{k}{2}})^2} \left(\frac{\frac{\beta\cdot E}{k}(-1)^{\frac{\beta^2}{k^2}+1}\Omega_{\frac{\beta}{k}}\left(y^{\frac{k}{2}}\right)}{\frac{\left(y^{\frac{k}{2}}\right)^{\frac{\beta\cdot E}{k}}-\left(y^{\frac{k}{2}}\right)^{-\frac{\beta\cdot E}{k}}}{y^{\frac{k}{2}}-y^{-\frac{k}{2}}}}-\sum_{g\geq 0}n_{g,\frac{\beta}{k}}(-1)^g(y^{\frac{k}{2}}-y^{-\frac{k}{2}})^{2g}\right)\]
can be derived from
\[\frac{-1}{(y^{\frac{1}{2}}-y^{-\frac{1}{2}})^2} \left(\frac{(\beta\cdot E)(-1)^{\beta^2+1 }\Omega_{\beta}\left(y^{\frac{1}{2}}\right)}{{\frac{\left(y^{\frac{1}{2}}\right)^{\beta\cdot E}-\left(y^{\frac{1}{2}}\right)^{-\beta\cdot E}}{y^{\frac{1}{2}}-y^{-\frac{1}{2}}}}}-\sum_{g\geq 0}n_{g,\beta}(-1)^g(y^{\frac{1}{2}}-y^{-\frac{1}{2}})^{2g}\right)\]
by replacing $y$ to $y^k$ and $\beta$ to $\frac{\beta}{k}$, and each
\begin{equation*}
\Cont_{T}\in\Q[y,y^{-1}]
\end{equation*}
by Lemma \ref{lem:key}. We can easily show by induction that
\begin{equation*}
\frac{-1}{(y^{\frac{1}{2}}-y^{-\frac{1}{2}})^2} \left(\frac{(\beta\cdot E)(-1)^{\beta^2+1}\Omega_{\beta}\left(y^{\frac{1}{2}}\right)}{{\frac{\left(y^{\frac{1}{2}}\right)^{\beta\cdot E}-\left(y^{\frac{1}{2}}\right)^{-\beta\cdot E}}{y^{\frac{1}{2}}-y^{-\frac{1}{2}}}}}-\sum_{g\geq 0}n_{g,\beta}(-1)^g(y^{\frac{1}{2}}-y^{-\frac{1}{2}})^{2g}\right)\in \Q[y,y^{-1}].
\end{equation*}
It then follows that
\[\frac{\Omega_{\beta}\left(y^{\frac{1}{2}}\right)}{{\frac{\left(y^{\frac{1}{2}}\right)^{\beta\cdot E}-\left(y^{\frac{1}{2}}\right)^{-\beta\cdot E}}{y^{\frac{1}{2}}-y^{-\frac{1}{2}}}}}\in \Q[y,y^{-1}].\]
But $\Omega_{\beta}\left(y^{\frac{1}{2}}\right)\in \mathbb{Z}[y^{ \frac{1}{2}},y^{-\frac{1}{2}}]$, so actually
\[\frac{\Omega_{\beta}\left(y^{\frac{1}{2}}\right)}{{\frac{\left(y^{\frac{1}{2}}\right)^{\beta\cdot E}-\left(y^{\frac{1}{2}}\right)^{-\beta\cdot E}}{y^{\frac{1}{2}}-y^{-\frac{1}{2}}}}}\in \Z[y,y^{-1}].\]
Notice that both $\Omega_{\beta}$ and $$\frac{\left(y^{\frac{1}{2}}\right)^{\beta\cdot E}-\left(y^{\frac{1}{2}}\right)^{-\beta\cdot E}}{y^{\frac{1}{2}}-y^{-\frac{1}{2}}}$$
are palindromic. So
\[\frac{\Omega_{\beta}\left(y^{\frac{1}{2}}\right)}{{\frac{\left(y^{\frac{1}{2}}\right)^{\beta\cdot E}-\left(y^{\frac{1}{2}}\right)^{-\beta\cdot E}}{y^{\frac{1}{2}}-y^{-\frac{1}{2}}}}}\]
is palindromic as well.
\end{proof}

\begin{rmk}\label{rmk:div+}
From the proof, we actually have a stronger conclusion:
\[\frac{-1}{(y^{\frac{1}{2}}-y^{-\frac{1}{2}})^2} \left(\frac{(\beta\cdot E)(-1)^{\beta^2+1}\Omega_{\beta}\left(y^{\frac{1}{2}}\right)}{{\frac{\left(y^{\frac{1}{2}}\right)^{\beta\cdot E}-\left(y^{\frac{1}{2}}\right)^{-\beta\cdot E}}{y^{\frac{1}{2}}-y^{-\frac{1}{2}}}}}-\sum_{g\geq 0}n_{g,\beta}(-1)^g(y^{\frac{1}{2}}-y^{-\frac{1}{2}})^{2g}\right)\in \Z[y,y^{-1}].\]
Note that here $n_{g,\beta} = 0$ if  $g>g(\beta)\coloneqq\frac{1}{2} \beta (K_S+\beta)+1$.
\end{rmk}

\subsection{Further analysis of the graph sum formula}
Assuming the refined sheaves/ Gromov-Witten correspondence (Conjecture \ref{conj:rsh/GW}), equation \eqref{eqn:sheaf/GW} in the proof of Theorem \ref{thm:main} provides a new way to computing the Betti numbers of $M_{\beta}$ via Gromov-Witten invariants of $K_S$ and a local elliptic curve.
We can reformulate the RHS of \eqref{eqn:sheaf/GW} as
\begin{equation}\label{eqn:contfm}
\sum_{T\in \RT_\beta,\atop t^{-1}(0)\neq \emptyset} \Cont_{T}=\sum_{k=0}^{\infty}\sum_{d_E,\beta_1,\cdots,\beta_k>0 \atop d_E [E]+\sum_{i=1}^k \beta_i=\beta}\frac{1}{|\Aut\boldsymbol{\beta}|}G^E_{d_E,\boldsymbol{\beta}}\prod_{i=1}^k \W^{K_S}_{\beta_i} ,
\end{equation}
where each $G^E_{d_E,\boldsymbol{\beta}}$ is a sum:
\[\sum_T\frac{|\Aut\boldsymbol{\beta}|}{|\Aut(T)|}
\prod_{e\in E_T}\frac{2\sin\frac{(d_2(e)\cdot E)\hbar}{2}}{d_2(e)\cdot E}\prod_{v_i\in t^{-1}(0)}\left(-F^{E,\tw}_{d^0(v_i),\{d_2(e_1^i),d_2(e_2^i),\cdots,d_2(e_{n_i}^i)\}}\right)\]
which takes over all the rooted trees $T$ such that $t^{-1}(0)\neq \emptyset$, the set of
labels
$$\{d^1(v_i)|v_i\in \V_T\}=\boldsymbol{\beta}=\{\beta_1,\cdots,\beta_k\},\quad \text{ and } \sum_{v_i\in V_T} d^0(v_i)=d_E.$$
By Corollary \ref{cor:rat}, each $G^E_{d_E,\boldsymbol{\beta}}$ is a palindromic Laurent polynomial of $y$ under the change of variables $y=e^{\sqrt{-1} \hbar}$. We have the following $y$-degree bounds for $G^E_{d_E,\boldsymbol{\beta}}$:
\begin{lem}\label{lem:degbd}
For $d_E>1$, we have
\begin{align*}
-\frac{(d_E-1)(d_E-2)K_S^2}{2}-(d_E-1)&\sum_{i=1}^k(-K_S\cdot \beta_i)\leq \deg_y(G^E_{d_E,\boldsymbol{\beta}})\\
&\leq \frac{(d_E-1)(d_E-2)K_S^2}{2}+(d_E-1)\sum_{i=1}^k(-K_S\cdot \beta_i).
\end{align*}
\end{lem}

\begin{proof}
Observe that any rooted tree can be constructed by starting with a star-shaped tree and attaching rooted trees to its leaves. Using this recursive structure alongside Theorem \ref{thm:keythm}, we can derive the following equation for
$G^E_{d_E,\boldsymbol{\beta}}$:
\begin{align}
& & 1  +\sum_{\rho} (-1)^{K_S^2 |\rho|} q^{|\rho|\cdot[E]} y^{K_S^2 c_{\rho}}\exp\Bigg(  \sum_{s\geq 0}\sum_{d_E\geq 0\atop \beta_1,\cdots,\beta_s>0}G_{d_E,\boldsymbol{\beta}}^E \cdot e_\rho(d_E,\boldsymbol{\beta})  q^{d_E[E]+\sum_{i=1}^s\beta_i}\frac{\prod_{i=1}^s p_{\beta_i}}{s!}\Bigg)\nonumber\\
& & = \exp\Bigg(-\sum_{s\geq 0}\sum_{d_E> 0\atop \beta_1,\cdots,\beta_s>0}G_{d_E,\boldsymbol{\beta}}^E q^{d_E[E]+\sum_{i=1}^s\beta_i}\frac{\prod_{i=1}^s p_{\beta_i}}{s!}\Bigg).
\label{eqn:treeid} \end{align}
Here $q$ and $p_{\beta}$ are formal variables, with $p_{\beta}$ indexed by nonzero effective curve classes $\beta$ of $S$. The exponents of $q$ are taken from the monoid of effective curve classes of $S$. The sum takes over all the partitions $\rho$. $e_\rho(d_E,\boldsymbol{\beta})$ is defined as
$$
e_\rho(d_E,\boldsymbol{\beta}) \coloneqq \tilde{e} (\rho,z )\cdot (e^{\frac{z}{2}}-e^{-\frac{z}{2}}) |_{z = (d_E K_S^2-\sum_{i=1}^s K_S\cdot \beta_i)\sqrt{-1}\hbar},
$$
where $\tilde{e} (\rho,z )$ is given by \eqref{eqn:tildeE}. We treat $e_\rho(d_E,\boldsymbol{\beta})$ as a Laurent polynomial of $y$, using the substitution $y=e^{i\hbar}$. Additionally, we define $G_{0,\boldsymbol{\beta}}^E$ as follows:
\[G_{0,\boldsymbol{\beta}}^E=
\begin{cases}
1, \text{ if }s=1,\\
0, \text{ otherwise,}
\end{cases}
\]
where $s$ is the cardinality of the set $\boldsymbol{\beta}=\{\beta_1,\cdots,\beta_s\}$.

One can easily deduce from \eqref{eqn:treeid} that
\begin{equation}\label{eqn:dE1fm}
G_{1,\boldsymbol{\beta}}^E=-(-1)^{K_S^2}\prod_{i=1}^s\Big(y^{-\frac{K_S\cdot\beta_i}{2}}-y^{\frac{K_S\cdot\beta_i}{2}}\Big)^2
\end{equation}
and
\[G_{2,\boldsymbol{\beta}}^E=-3\cdot 2^{s-1}\prod_{i=1}^s\Big(y^{-\frac{K_S\cdot\beta_i}{2}}-y^{\frac{K_S\cdot\beta_i}{2}}\Big)^2.\]
The above computation shows that Lemma \ref{lem:degbd} holds for $d_E=2$ and $\forall k$.
In order to prove the lemma, we will perform induction on integers $d_E$. Assume that the lemma holds for $ 2\leq d_E<d$ and $\forall k$. We want to prove that
\begin{align*}
-\frac{(d_E-1)(d_E-2)K_S^2}{2}-(d_E-1)&\sum_{i=1}^k(-K_S\cdot \beta_i)\leq \deg_y(G^E_{d_E,\boldsymbol{\beta}})\\
&\leq \frac{(d_E-1)(d_E-2)K_S^2}{2}+(d_E-1)\sum_{i=1}^k(-K_S\cdot \beta_i).
\end{align*}
holds for $d_E=d$ and $\forall k$. Since $G^E_{d,\boldsymbol{\beta}}$ is invariant under the change of $y\rightarrow y^{-1}$, we only need to prove that
\begin{equation}\label{eqn:iduceq}
\deg_y(G^E_{d,\boldsymbol{\beta}})\leq \frac{(d-1)(d-2)K_S^2}{2}+(d-1)\sum_{i=1}^k(-K_S\cdot \beta_i)
\end{equation}
holds for $\forall k$. Let
\[H(q,p_{\beta_i},y)\coloneqq\exp\Bigg(-\sum_{s\geq 0}\sum_{d_E> 0\atop \beta_1,\cdots,\beta_s>0}G_{d_E,\boldsymbol{\beta}}^E q^{d_E[E]+\sum_{i=1}^s\beta_i}\frac{\prod_{i=1}^s p_{\beta_i}}{s!}\Bigg)\]
and
\[L(q,p_{\beta_i})\coloneqq \exp\Bigg(\sum_{\beta_i>0} q^{\beta_i}p_{\beta_i}\Bigg),\qquad I(q,p_{\beta_i},y)\coloneqq \frac{H}{L}.\]
Then using the equality:
\[\tilde{e} (\rho,z )\cdot (e^{\frac{z}{2}}-e^{-\frac{z}{2}})=\sum_{\square\in\rho}\left(e^{(c(\square)+1)z}-2e^{c(\square)z}+e^{(c(\square)-1)z}\right),\]
we could rewrite \eqref{eqn:treeid} as
\begin{equation}\label{eqn:treeid2}
\begin{split}
1+\sum_{\rho}\prod_{\square\in\rho}(-1)^{K_S^2}q^{[E]}y^{c(\square)K_S^2}\frac{I(qy^{-c(\square)K_S},p_{\beta_i},y)^2}{I(qy^{-(c(\square)+1)K_S},p_{\beta_i},y)I(qy^{-(c(\square)-1)K_S},p_{\beta_i},y)}&\\
=H(q,p_{\beta_i},y).
\end{split}
\end{equation}
Here each partition $\rho$ corresponds to a Young diagram. For a box $\square$ located at position $(i,j)$ within a Young diagram, the content is defined as $c(\square)=j-i$. When substituting the variable
$q\rightarrow qy^{nK_S}$ with $n\in \Z$, it is important to interpret this substitution carefully: the exponent of $q$ is always an effective curve class $\beta$. After performing the substitution $q\rightarrow qy^{nK_S}$, the term $q^{\beta}$ transforms into $q^{\beta}y^{n(K_S\cdot\beta)}$.

By induction, it is easy to see that inequality
\eqref{eqn:iduceq} is equivalent to
\begin{equation}\label{eqn:iduceq2}
\deg_y\Big(\Big[q^{d[E]}\prod_{i=1}^k q^{\beta_i}p_{\beta_i}\Big]H(q,p_{\beta_i},y)\Big)\leq \frac{(d-1)(d-2)K_S^2}{2}+(d-1)\sum_{i=1}^k(-K_S\cdot \beta_i)
\end{equation}
where $\Big[q^{d[E]}\prod_{i=1}^k q^{\beta_i}p_{\beta_i}\Big]$ means we take the $q^{d[E]}\prod_{i=1}^k q^{\beta_i}p_{\beta_i}$-coefficient of $H$. The inequality \eqref{eqn:iduceq2} can be derived
by a detailed analysis of the LHS of \eqref{eqn:treeid2} as follows:

Given a partition $\rho=(\rho_1\geq \rho_2\geq \cdot \geq \rho_l)$, one could easily check by induction that if $l\geq 2$, i.e., $\rho $ contains at least 2 parts, then the $y$-degree of the $q^{d[E]}\prod_{i=1}^k q^{\beta_i}p_{\beta_i}$-coefficient in the summand
\[\prod_{\square\in\rho}(-1)^{K_S^2}q^{[E]}y^{c(\square)K_S^2}\frac{I(qy^{-c(\square)K_S},p_{\beta_i},y)^2}{I(qy^{-(c(\square)+1)K_S},p_{\beta_i},y)I(qy^{-(c(\square)-1)K_S},p_{\beta_i},y)}\]
on the LHS of \eqref{eqn:treeid2} is at most
\[\frac{(d-1)(d-2)K_S^2}{2}-K_S^2+(d-1)\sum_{i=1}^k(-K_S\cdot \beta_i).\]
So we only need to show that the $y$-degree of the $q^{d[E]}\prod_{i=1}^k q^{\beta_i} p_{\beta_i}$-coefficient in the sum
\begin{equation}\label{eqn:1part}
\sum_{m=1}^d\prod_{\square\in (m)}(-1)^{K_S^2}q^{[E]}y^{c(\square)K_S^2}\frac{I(qy^{-c(\square)K_S},p_{\beta_i},y)^2}{I(qy^{-(c(\square)+1)K_S},p_{\beta_i},y)I(qy^{-(c(\square)-1)K_S},p_{\beta_i},y)}
\end{equation}
is at most
\[\frac{(d-1)(d-2)K_S^2}{2}+(d-1)\sum_{i=1}^k(-K_S\cdot \beta_i)\]
where $(m)$ stands for the partition contains only one part $m$. We use $H_d^1(q,p_{\beta_i},y)$ to denote \eqref{eqn:1part} plus one. Then we can rewrite \eqref{eqn:1part} as
\[(-1)^{K_S^2}q^{[E]}\frac{I(q,p_{\beta_i},y)^2}{I(qy^{K_S},p_{\beta_i},y)I(qy^{-K_S},p_{\beta_i},y)} H_{d-1}^1(qy^{-K_S},p_{\beta_i},y).\]
We use $I_d$ (resp. $H_d$ and $L_d$) to denote a truncation of $I$ (resp. $H$ and $L$) which contains terms in $I$ (resp. $H$ and $L$) whose $q$-degrees are at most $d[E]$ after a replacement of $p_{\beta_i}$ by $q^{-\beta_i}p_{\beta_i}$\footnote{After the replacement of $p_{\beta_i}$ by $q^{-\beta_i}p_{\beta_i}$, the power of $z$ is always in the form of $m[E]$, $m\in\Z_{\geq 0}$.}. So we only need to show that  the $y$-degree of the $q^{(d-1)[E]}\prod_{i=1}^k q^{\beta_i} p_{\beta_i}$-coefficient in
\[
\frac{I_{d-1}(q,p_{\beta_i},y)^2L_{d-1}(qy^{-K_S},p_{\beta_i},y)}{I_{d-1}(qy^{K_S},p_{\beta_i},y)}\frac{H_{d-1}^1(qy^{-K_S},p_{\beta_i},y)}{H_{d-1}(qy^{-K_S},p_{\beta_i},y)}
\]
is at most
\[\frac{(d-1)(d-2)K_S^2}{2}+(d-1)\sum_{i=1}^k(-K_S\cdot \beta_i).\]
This follows from the induction and the fact that $H_{d-1}(qy^{-K_S},p_{\beta_i},y)$ can be written as
$$H_{d-1}^1(qy^{-K_S},p_{\beta_i},y)+H_{d-1}^2(qy^{-K_S},p_{\beta_i},y)$$
where the $y$-degree of the $q^{m[E]}\prod_{i=1}^k q^{\beta_i} p_{\beta_i}$-coefficient in $H_{d-1}^2(qy^{-K_S},p_{\beta_i},y)$ is at most
\[\frac{m(m-1)K_S^2}{2}+m\sum_{i=1}^k(-K_S\cdot \beta_i),\qquad m\leq d-1.\]
The latter $y$-degree bound follows from the fact that $H_{d-1}^2(q,p_{\beta_i},y)$ is a sum over partitions $\rho$ contains at least 2 parts and $|\rho|\leq d-1$, i.e.,
\[\sum_{\rho=(\rho_1\geq \cdots \geq\rho_l)\atop l\geq 2, |\rho|\leq d-1}\prod_{\square\in\rho}(-1)^{K_S^2}q^{[E]}y^{c(\square)K_S^2}\frac{I(qy^{-c(\square)K_S},p_{\beta_i},y)^2}{I(qy^{-(c(\square)+1)K_S},p_{\beta_i},y)I(qy^{-(c(\square)-1)K_S},p_{\beta_i},y)}.\]
\end{proof}


\section{A closed formula for leading Betti numbers}\label{sec:Leading}


In this section, we aim to give a closed formula for the leading Betti numbers when $S=\PP^2$ since the refined sheaves/Gromov-Witten correspondence is known to hold in this case.
Specifically, we use $\Omega^{\mathbb P^2}_d$ to denote the shifted Poincar\'e polynomial of the moduli space of Gieseker stable sheaves on $\PP^2$ supported on curves with degree $d\in \Z_{>0}$ and Euler characteristic $1$.


\subsection{Degree analysis}\label{subsec:degbd}
We set
\[\mathcal  F_d(y)\coloneqq\sum_{g\geq 0}n_{g,d}(-1)^g(y^{\frac{1}{2}}-y^{-\frac{1}{2}})^{2g}\]
where $n_{g,d}$ are the genus $g$, degree $d$ Gopakumar-Vafa invariants of local $\PP^2$. Note that for fixed $d$,
\[n_{g,d}=0,\,\text{ if }g>g(d)\coloneqq\frac{(d-1)(d-2)}{2}. \]
Using Lemma \ref{lem:degbd}, we could deduce the following degree bound:
\begin{prop}\label{prop:degbd1}
Let
$$
\mathcal X_d\coloneqq \frac{3d (-1)^{d^2+1}\Omega_{d}\left(y^{\frac{1}{2}}\right)}{{\frac{y^{\frac{3d}{2}} -y^{-\frac{3d}{2}}}{y^{\frac{1}{2}}-y^{-\frac{1}{2}}}}}- \mathcal  F_d(y) - \big(y^{\frac{3(d-3) }{2}}-y^{-\frac{3(d-3) }{2}}\big)^2 \cdot  \mathcal F_{d-3}(y).$$
Then for $d\geq 5$,
$$
\mathcal X_d \in  \  \Z[y,y^{-1}]_{ -g(d) +d-4 \leq \deg \leq g(d)-d+4 }.
$$
\end{prop}
\begin{proof}
By Theorem \ref{thm:main}, it is obvious that $\mathcal X_d\in  \Z[y,y^{-1}]$. Furthermore, $\mathcal X_d$ is invariant under the change of $y\rightarrow y^{-1}$. So we only need to show the upper bound, i.e.,
\begin{equation}\label{eqn:mainineq1}
\deg_y(\mathcal X_d)\leq g(d)-d+4,\quad \text{ for } d\geq 5.
\end{equation}

Combining equations \eqref{eqn:sheaf/GW} and \eqref{eqn:contfm}, we have
\begin{equation}\label{eqn:key2bd}
\begin{aligned}
\ & \sum_{k|d} \frac{(y^{\frac{1}{2}}-y^{-\frac{1}{2}})^2}{k(y^{\frac{k}{2}}-y^{-\frac{k}{2}})^2} \left(\frac{\frac{3d}{k}(-1)^{\frac{d^2}{k^2}+1}\Omega_{\frac{d}{k}}\left(y^{\frac{k}{2}}\right)}{\frac{\left(y^{\frac{k}{2}}\right)^{\frac{3d}{k}}-\left(y^{\frac{k}{2}}\right)^{-\frac{3d}{k}}}{y^{\frac{k}{2}}-y^{-\frac{k}{2}}}}-\sum_{g\geq 0}n_{g,\frac{d}{k}}(-1)^g(y^{\frac{k}{2}}-y^{-\frac{k}{2}})^{2g}\right)\\
= \ & \sum_{k=0}^{\infty}\sum_{d_E,d_1,\cdots,d_k>0 \atop 3d_E +\sum_{i=1}^k d_i=d}\frac{-(y^{\frac{1}{2}}-y^{-\frac{1}{2}})^2}{|\Aut\{d_1,\cdots,d_k\}|}G^E_{d_E,\{d_1,\cdots,d_k\}}\prod_{i=1}^k \W^{K_{\PP^2}}_{d_i}.
\end{aligned}
\end{equation}
after further multiplying both sides by $-(y^{\frac{1}{2}}-y^{-\frac{1}{2}})^2$. Note that if $k=1$, then the summand on the LHS of \eqref{eqn:key2bd} becomes
\[\frac{3d (-1)^{d^2+1}\Omega_{d}\left(y^{\frac{1}{2}}\right)}{{\frac{y^{\frac{3d}{2}} -y^{-\frac{3d}{2}}}{y^{\frac{1}{2}}-y^{-\frac{1}{2}}}}}- \mathcal  F_d(y).\]
If $k> 1$, then by Remark \ref{rmk:div+}, the summand
\[ \frac{(y^{\frac{1}{2}}-y^{-\frac{1}{2}})^2}{k(y^{\frac{k}{2}}-y^{-\frac{k}{2}})^2} \left(\frac{\frac{3d}{k}(-1)^{\frac{d^2}{k^2}+1}\Omega_{\frac{d}{k}}\left(y^{\frac{k}{2}}\right)}{\frac{\left(y^{\frac{k}{2}}\right)^{\frac{3d}{k}}-\left(y^{\frac{k}{2}}\right)^{-\frac{3d}{k}}}{y^{\frac{k}{2}}-y^{-\frac{k}{2}}}}-\sum_{g\geq 0}n_{g,\frac{d}{k}}(-1)^g(y^{\frac{k}{2}}-y^{-\frac{k}{2}})^{2g}\right)\in\Z[y,y^{-1}].\]
The $y$-degree upper bound of the above summand can be easily computed:
\[\frac{d^2}{2k}-\frac{3d}{2}+1.\]
One can easily verify that if $k\geq 2$, then
\begin{equation}\label{eqn:k2ineq}
\frac{d^2}{2k}-\frac{3d}{2}+1\leq g(d)-d+1<g(d)-d+4,\quad \forall d\in \Z_{>0}.
\end{equation}
For each summand on the RHS of \eqref{eqn:key2bd},
\[\frac{-(y^{\frac{1}{2}}-y^{-\frac{1}{2}})^2}{|\Aut\{d_1,\cdots,d_k\}|}G^E_{d_E,\{d_1,\cdots,d_k\}}\prod_{i=1}^k \W^{K_{\PP^2}}_{d_i}\in\Q[y,y^{-1}]\]
by Lemma \ref{lem:key}. If $d_E>1$, then by Lemma \ref{lem:degbd}, we have
\begin{align*}
     & \deg_y\Big((y^{\frac{1}{2}}-y^{-\frac{1}{2}})^2G^E_{d_E,\{d_1,\cdots,d_k\}}\prod_{i=1}^k \W^{K_{\PP^2}}_{d_i}\Big)\\
 \leq \ & 1+\frac{9(d_E-1)(d_E-2)}{2}+(d_E-1)\sum_{i=1}^k (3d_i)+\sum_{i=1}^k\Big(\frac{d_i^2}{2}-\frac{3d_i}{2}\Big)\\
 =   \  & \frac{(3d_E+\sum_{i=1}^k d_i)^2}{2}-\frac{9(3d_E+\sum_{i=1}^k d_i)}{2}+10-\sum_{1\leq i<j \leq k}d_id_j\\
 =  \  & g(d)-(3d-9+\sum_{1\leq i<j \leq k}d_id_j) \quad \text{ Here we use } 3d_E+\sum_{i=1}^k d_i=d\\
 <  \  & g(d)-d+4,\quad \text{if }d\geq 5.
\end{align*}
If $d_E=1$, then by \eqref{eqn:dE1fm}, one can easily compute that
\begin{equation}\label{eqn:dE1deg}
\deg_y\Big((y^{\frac{1}{2}}-y^{-\frac{1}{2}})^2G^E_{1,\{d_1,\cdots,d_k\}}\prod_{i=1}^k \W^{K_{\PP^2}}_{d_i}\Big)=g(d)-\sum_{1\leq i<j \leq k}d_i d_j.
\end{equation}
Note that in this case, $\sum_{i=1}^k d_i=d-3$ and $d_i\in\Z_{>0}$, one can easily show that
\[\sum_{1\leq i<j \leq k} d_i d_j\geq d-4,\,\text{ if }k\geq 2.\]
So the only summand on the RHS of \eqref{eqn:key2bd} whose $y$-degree is greater than $g(d)-d+4$ is the case $d_E=1$ and $k=1$, i.e.,
\begin{align*}
     & -(y^{\frac{1}{2}}-y^{-\frac{1}{2}})^2 G_{1,{d-3}}^E\W^{K_{\PP^2}}_{d-3}\\
     \stackrel{\text{by \eqref{eqn:dE1fm}}}{=} \  & \big(y^{\frac{3(d-3) }{2}}-y^{-\frac{3(d-3) }{2}}\big)^2\sum_{k|(d-3)}\frac{(y^{\frac{1}{2}}-y^{-\frac{1}{2}})^2}{k(y^{\frac{k}{2}}-y^{-\frac{k}{2}})^2} \mathcal  F_{\frac{d-3}{k}}(y^{k}).
\end{align*}
Using a similar inequality as \eqref{eqn:k2ineq}, we have
\[\deg_y\Big(\big(y^{\frac{3(d-3) }{2}}-y^{-\frac{3(d-3) }{2}}\big)^2\frac{(y^{\frac{1}{2}}-y^{-\frac{1}{2}})^2}{k(y^{\frac{k}{2}}-y^{-\frac{k}{2}})^2} \mathcal  F_{\frac{d-3}{k}}(y^{k})\Big)\leq g(d)-d+4,\quad \text{ if }k>1.\]
From the above analysis, we may conclude that only the term
\[\big(y^{\frac{3(d-3) }{2}}-y^{-\frac{3(d-3) }{2}}\big)^2 \cdot  \mathcal F_{d-3}(y)\]
on the LHS of \eqref{eqn:key2bd} has degree greater than $g(d)-d+4$. Now inequality \eqref{eqn:mainineq1} follows from the above analysis.
\end{proof}

\begin{rmk}
For $d<5$, we have a better degree bound. Actually, by the computation in Section \ref{sec:Nume}, we have
\[\mathcal X_d=
\begin{cases}
0,\quad \text{ if }d=1,2,4,\\
-(y^{\frac{1}{2}}-y^{-\frac{1}{2}})^2,\quad \text{ if }d=3.
\end{cases}
\]
where we set $\mathcal F_d=0$ if $d\leq 0$.
\end{rmk}


Furthermore, we have the following stronger result when $d\geq 6$:
\begin{prop} \label{prop:degbd2}
Let
$$
\mathcal Y_d\coloneqq\mathcal X_d  + n_{0,1} \left( \frac{ y^{\frac{3 }{2}}-y^{-\frac{3 }{2}}}{y^{\frac{1}{2}}-y^{-\frac{1 }{2}}}\right)^2 \big(y^{\frac{3(d-4) }{2}}-y^{-\frac{3(d-4) }{2}}\big)^2\cdot  \mathcal F_{d-4}
$$
where $n_{0,1}=3$ is the genus $0$, degree $1$ Gopakumar-Vafa invariants of local $\PP^2$. Then for $d\geq 6$,
$$
\mathcal Y_d \in \Z[y,y^{-1}]_{ -g(d) +2d-10 \leq \deg \leq g(d)-2d+10 }.
$$
\end{prop}
\begin{proof}
The proof is similar to Proposition \ref{prop:degbd1}. The only difference is that there will be a new summand on the RHS of \eqref{eqn:key2bd} whose $y$-degree is greater than $g(d)-2d+10$:
\begin{align*}
& \frac{-(y^{\frac{1}{2}}-y^{-\frac{1}{2}})^2}{|\Aut\{1,d-4\}|}G^E_{1,\{1,d-4\}}\W^{K_{\PP^2}}_{1}\W^{K_{\PP^2}}_{d-4}\\
 \stackrel{\text{by \eqref{eqn:dE1fm}}}{=}  \ & - n_{0,1} \left( \frac{ y^{\frac{3 }{2}}-y^{-\frac{3 }{2}}}{y^{\frac{1}{2}}-y^{-\frac{1 }{2}}}\right)^2 \big(y^{\frac{3(d-4) }{2}}-y^{-\frac{3(d-4) }{2}}\big)^2\sum_{k|(d-4)}\frac{(y^{\frac{1}{2}}-y^{-\frac{1}{2}})^2}{k(y^{\frac{k}{2}}-y^{-\frac{k}{2}})^2} \mathcal  F_{\frac{d-4}{k}}(y^{k}).
\end{align*}
One can similarly show that only the $k=1$ term
\[-n_{0,1} \left( \frac{ y^{\frac{3 }{2}}-y^{-\frac{3 }{2}}}{y^{\frac{1}{2}}-y^{-\frac{1 }{2}}}\right)^2 \big(y^{\frac{3(d-4) }{2}}-y^{-\frac{3(d-4) }{2}}\big)^2\cdot  \mathcal F_{d-4}\]
has $y$-degree greater than $g(d)-2d+10$. It then follows that
\[\deg_y\mathcal Y_d\leq g(d)-2d+10.\]
Since $\mathcal Y_d$ is also invariant under the change of  $y\rightarrow y^{-1}$, the lower bound also follows.
\end{proof}

\subsection{Proof of Theorem \ref{thm:leadingBetti}}
To prove Theorem \ref{thm:leadingBetti}, it is crucial to understand the leading Gopakumar-Vafa invariants of $K_{\PP^2}$. These invariants were explicitly computed by the first author and Zhou using the topological vertex formula in \cite{GZ15}:
\begin{thm}[\cite{GZ15}] \label{thm:gvbd}
Let
\begin{align*}
\mathcal Z_d  & =  \frac{(1-y)^2 }{ \prod_{k>0}(1-y^{k})^3}  \cdot \left(  \binom{d+2}{2}  -3 \sum_{i\geq 1 } \frac{y^i}{(1-y^i)^2} \right),\\
\mathcal Z'_d & = \frac{ (1-y^3)}{ \prod_{k>0}(1-y^{k})^3} \cdot \left(  \binom{d+1}{2}  -3 \sum_{i\geq 1 } \frac{y^i}{(1-y^i)^2} -3  \frac{y^3}{(1-y^3) }\right),
\end{align*}
then  we have
\begin{align*}
 (-1)^{d-1}  y^{g(d)}\cdot \mathcal F_d - \mathcal Z_d  \ & \in \ y^{ d-1}\cdot \mathbb \Z[[y]],\quad \text{if } d\geq 1,\\
(-1)^{d-1} y^{g(d)}\cdot \mathcal F_d - \mathcal Z_d +3 \,y^{d-1}\cdot \mathcal Z'_d \ & \in \ y^{2d-4}\cdot \mathbb \Z[[y]],\quad \text{if } d\geq 3.
\end{align*}
\end{thm}

These $\mathcal Z_d$ and $\mathcal Z'_d$ satisfy the following equations:
\begin{lem}\label{lem:1st}
For $d\geq 4$,
\begin{align*}
   \frac{1}{3d} \left( \mathcal Z_d    -  \mathcal Z_{d-3}  \right)   =    \prod_{k>0}\frac{1}{(1-y^{k})(1-y^{k+1})^2}.
\end{align*}
\end{lem}
\begin{proof}
This directly follows from Theorem \ref{thm:gvbd}.
\end{proof}

\begin{lem}\label{lem:2nd}
For $d\geq 5$,
 \begin{align*}
 & \ \frac{1}{3d} \cdot \left(  - y^{d-1} \cdot \mathcal Z'_d   +  y^{d-4} \cdot \mathcal Z'_{d-3}    -y^{d-4}(1+y+y^2)^2 \cdot \mathcal Z_{d-4}    \right) \\
 = & \  \frac{-y^{d-1}(1+y+y^2)}{\prod_{k>0}(1-y^{k})^2(1-y^{k+1})}.
\end{align*}
\end{lem}
\begin{proof}
This just follows from the direct computation:
 \begin{align*}
 \mathrm{LHS}  \ =  \ \frac{y^{d-1}}{3d} \bigg[  \ &  \frac{ -(1-y^3)}{ \prod_{k>0}(1-y^{k})^3} \cdot \left(  \binom{d+1}{2}  -3 \sum_{i\geq 1 } \frac{y^i}{(1-y^i)^2} -3  \frac{y^3}{(1-y^3) }\right)  \\
 \ &  +\frac{ y^{-3} \,(1-y^3)}{ \prod_{k>0}(1-y^{k})^3} \cdot \left(  \binom{d-2}{2}  -3 \sum_{i\geq 1 } \frac{y^i}{(1-y^i)^2} -3  \frac{y^3}{(1-y^3) }\right)  \\
 \ &   - \frac{ y^{-3}(1-y^3)^2}{ \prod_{k>0}(1-y^{k})^3} \cdot \left(  \binom{d-2}{2}  -3 \sum_{i\geq 1 } \frac{y^i}{(1-y^i)^2} \right)  \bigg]\\
\  =  \ \frac{y^{d-1}}{3d} \bigg[  \ &  \frac{ -(1-y^3)}{ \prod_{k>0}(1-y^{k})^3} \cdot \left(  \binom{d+1}{2}  -3 \sum_{i\geq 1 } \frac{y^i}{(1-y^i)^2} -3  \frac{y^3}{(1-y^3) }\right)  \\
 \ &  +\frac{ y^{-3} \,(1-y^3)}{ \prod_{k>0}(1-y^{k})^3} \cdot \left(  \binom{d-2}{2}  -3 \sum_{i\geq 1 } \frac{y^i}{(1-y^i)^2} -3  \frac{y^3}{(1-y^3) }\right)  \\
 \ &   -\frac{ y^{-3}(1-y^3)}{ \prod_{k>0}(1-y^{k})^3} \cdot \left(  \binom{d-2}{2}  -3 \sum_{i\geq 1 } \frac{y^i}{(1-y^i)^2} \right)\\
 \ & +  \frac{(1-y^3)}{ \prod_{k>0}(1-y^{k})^3} \cdot \left(  \binom{d-2}{2}  -3 \sum_{i\geq 1 } \frac{y^i}{(1-y^i)^2} \right)
 \bigg]\\
 \  =  \frac{y^{d-1}}{3d} \cdot\bigg[  \ &  \frac{- (1-y^3)}{ \prod_{k>0}(1-y^{k})^3} \cdot \left(  \binom{d+1}{2}  - \binom{d-2}{2} -3  \frac{y^3}{(1-y^3) }+ 3 \frac{1}{(1-y^3) }\right) \bigg]   \\
\  =  \frac{y^{d-1}}{3d} \cdot\bigg[  \ &  \frac{- (1-y^3)}{ \prod_{k>0}(1-y^{k})^3} \cdot \left(  3d-3 - 3\frac{y^3}{(1-y^3) }+ 3 \frac{1}{(1-y^3) }\right) \bigg]  \ =   \mathrm{RHS}.
\end{align*}
\end{proof}

We are ready to give a closed formula for the leading Betti numbers of $M_d$.
\begin{thm}[=Theorem \ref{thm:leadingBetti}]\label{thm:2nd}
For $d\geq 6$, we have
$$
\hat{\Omega}^{\mathbb P^2}_d =  \prod_{k>0} \frac{1}{(1-y^{k})(1-y^{k+1})^{2}} \Big( 1 - 3\,y^{d-1}\cdot \frac{ 1+  y + y^2   }{1-y}  \Big) \bigg|_{y^{\leq 2d-11}} +O ({y^{ 2d-10}}).
$$
\end{thm}

\begin{proof}
Recall that
$$\hat{\Omega}^{\mathbb P^2}_d= y^{\frac{(d-1)(d-2)}{2}}\cdot \frac{\Omega^{\mathbb P^2}_d}{{{\frac{\left(y^{\frac{1}{2}}\right)^{3d}-\left(y^{\frac{1}{2}}\right)^{-3d}}{y^{\frac{1}{2}}-y^{-\frac{1}{2}}}}}}.$$
By Proposition \ref{prop:degbd2}, to compute the coefficients of $\hat{\Omega}^{\mathbb P^2}_d$ up to degree $2d-11$, we only need to compute the coefficients of
\[(-1)^{d-1}y^{g(d)}\mathcal F_d+(-1)^{d-1}y^{g(d)-3d+9}\mathcal F_{d-3}-(-1)^{d-1}n_{0,1}(1+y+y^2)^2 y^{g(d)-3d+10}\mathcal F_{d-4}\]
up to degree $2d-11$. By Theorem \ref{thm:gvbd}, it equals to
\begin{align*}
 & \mathcal Z_d-3y^{d-1}\mathcal Z'_{d}-(\mathcal Z_{d-3}-3y^{d-4}\mathcal Z'_{d-3})-3y^{d-4}(1+y+y^2)^2\mathcal Z_{d-4}+O ({y^{ 2d-10}})\\
= \ & \mathcal Z_d-\mathcal Z_{d-3}+3 \left(  - y^{d-1} \cdot \mathcal Z'_d   +  y^{d-4} \cdot \mathcal Z'_{d-3}    -y^{d-4}(1+y+y^2)^2 \cdot \mathcal Z_{d-4}    \right)+O ({y^{ 2d-10}}).
\end{align*}
After further dividing by $3d$ and using Lemmas \ref{lem:1st} and \ref{lem:2nd}, we can deduce that
$$
\hat{\Omega}^{\mathbb P^2}_d =  \prod_{k>0} \frac{1}{(1-y^{k})(1-y^{k+1})^{2}} \Big( 1 - 3\,y^{d-1}\cdot \frac{ 1+  y + y^2   }{1-y}  \Big) \bigg|_{y^{\leq 2d-11}} +O ({y^{ 2d-10}}).
$$
for $d\geq 6$.
\end{proof}


